	@Test
	void termKindProofRetainsFrozenAliasesAndBooleanStructure() {
		ValueExpr expression = new Or(new IsLiteral(new Var("left")),
				new Not(new IsLiteral(new Var("right"))));
		NativeScalarPlan plan = NativeScalarPlan.create(expression, name -> name.equals("left") ? 3 : 7,
				NativeScalarPlan.ResultKind.BOOLEAN, false, 0L, false, false);

		KernelTermKindProof proof = plan.termKindProof(new int[] { 3, 7 });
		int literal = 1 << ValueIds.TERM_KIND_LITERAL;
		int iri = 1 << ValueIds.TERM_KIND_IRI;
		assertThat(proof.evaluate(index -> index == 0 ? literal : iri)).isEqualTo(KernelTermKindProof.TRUE_BIT);
		assertThat(proof.canonicalKey()).isEqualTo("or(kind(0,0x4),not(kind(1,0x4)))");

		NativeScalarPlan aliasPlan = NativeScalarPlan.create(new IsLiteral(new Var("alias")), name -> 3,
				NativeScalarPlan.ResultKind.BOOLEAN, false, 0L, false, false);
		assertThat(aliasPlan.termKindProof(new int[] { 3 })).isEqualTo(
				KernelTermKindProof.forKind(0, literal));
	}

	@Test
	void termKindProofWidenedForConstantsAndUnknownExpressions() {
		NativeScalarPlan constant = planOf(new IsLiteral(new ValueConstant(literal("constant"))));
		NativeScalarPlan unknown = planOf(new MathExpr(new Var("value"), new ValueConstant(literal("1")),
				MathExpr.MathOp.PLUS));

		assertThat(constant.termKindProof(new int[] { 0 }).evaluate(ignored -> 1 << ValueIds.TERM_KIND_IRI))
				.isEqualTo(KernelTermKindProof.ALL_OUTCOMES);
		assertThat(unknown.termKindProof(new int[] { 0 }).canonicalKey()).isEqualTo("unknown");
	}

	private static NativeScalarPlan planOf(ValueExpr expression) {
		return NativeScalarPlan.create(expression, name -> 0, NativeScalarPlan.ResultKind.VALUE, false, 0L, true, true);
	}

	private static LmdbNativeSlotReader reader(long... ids) {
		return new LmdbNativeSlotReader() {
			@Override
			public long id(int slot) {
				return ids[slot];
			}
		};
	}

	private static LmdbNativeValueCodec.DecodedValue stringValue(String value) {
		return LmdbNativeValueCodec.DecodedValue.literal(value, null,
				CoreDatatype.XSD.STRING.getIri().stringValue(), CoreDatatype.XSD.STRING);
	}

	private static Value literal(String value) {
		return SimpleValueFactory.getInstance().createLiteral(value);
	}
